#!/usr/bin/env node
/*
 * generate-plugin — the coding-agent packages under plugin/, plugin-copilot/
 * and skills/, written from the skills and the app guide instead of by hand.
 *
 * Three outputs, one source:
 *
 *   plugin/          the Claude Code plugin. This repository is a Claude Code
 *                    plugin marketplace (`.claude-plugin/marketplace.json`), so
 *                    an app developer gets the skills and the MCP server with
 *                      /plugin marketplace add abap2UI5/abap2UI5
 *                      /plugin install abap2ui5@abap2ui5
 *   plugin-copilot/  the same plugin for GitHub Copilot - the CLI's plugin
 *                    format (manifest, `agents/*.agent.md`, `skills/`,
 *                    `commands/*.md`, `.mcp.json`), plus the five commands as
 *                    prompt files for VS Code (`prompts/*.prompt.md`):
 *                      copilot plugin install abap2UI5/abap2UI5:plugin-copilot
 *   skills/          the four skills in the open Agent Skills format
 *                    (agentskills.io), where `npx skills add abap2UI5/abap2UI5`
 *                    and SAP's ai-skills-library look for them, so they load in
 *                    Cursor, Codex, Copilot and every other agent the `skills`
 *                    CLI knows.
 *
 * WHY THE PLUGIN IS A FOLDER OF ITS OWN, and not the repository root with
 * `"skills": "./.claude/skills/"` in its manifest. That was the first shape,
 * and it installs: Claude Code copies a marketplace plugin into its cache and,
 * when the plugin root holds a package.json AND a lockfile, runs the package
 * install there - with no way to turn it off. The root of this repository has
 * both, so every user got the framework's whole devDependency tree (abaplint,
 * Playwright, the UI5 tooling): 166 MB in the cache for four Markdown files,
 * again for every version, and a plugin listed as half-installed whenever the
 * 60-second install budget ran out. A plugin may not reach outside its own
 * root either (a `..` path or a symlink out of it is refused), so the files
 * have to be IN plugin/ - which makes them copies, and a copy is the thing
 * CONVENTIONS §5 says is generated or gated. This is both. The Copilot plugin
 * and the root skills are copies for the same reason, generated by the same
 * run and gated by the same check.
 *
 * What it writes:
 *
 *   plugin/skills/<name>/SKILL.md            from .claude/skills/<name>/SKILL.md
 *   plugin/docs/agents/building-apps.md      from docs/agents/building-apps.md
 *   skills/<name>/SKILL.md                   the portable copy: `license` and
 *                                            `metadata` in the frontmatter, the
 *                                            guide as a `references/` file
 *   skills/build-an-app/references/building-apps.md
 *   plugin-copilot/skills/...                identical to skills/
 *   plugin-copilot/plugin.json               from plugin/.claude-plugin/plugin.json
 *   plugin-copilot/.mcp.json                 the MCP server from the same manifest
 *   plugin-copilot/agents/abap2ui5-reviewer.agent.md
 *                                            from plugin/agents/abap2ui5-reviewer.md
 *   plugin-copilot/commands/abap2ui5-<cmd>.md
 *   plugin-copilot/prompts/abap2ui5-<cmd>.prompt.md
 *                                            both from plugin/commands/<cmd>.md
 *
 * The guide travels with the skills because `build-an-app` is a pointer at it
 * ("the guide is the content"), and a pointer at a file the plugin user does
 * not have is a skill that sends the agent looking for nothing. The Claude
 * copy keeps the path it has here, so the one sentence that names it only has
 * to say where the plugin is; the portable copies carry it as
 * `references/building-apps.md` inside the skill folder, the layout the Agent
 * Skills specification recommends and the one the `skills` CLI copies whole.
 *
 * Hand-written, and not touched here: `plugin/.claude-plugin/plugin.json`
 * (the manifest, with the MCP server inline - see the repository map for why
 * not a `.mcp.json`), the three READMEs, the slash commands under
 * `plugin/commands/`, the subagent under `plugin/agents/` and the hook under
 * `plugin/hooks/`. The commands, the agent and the hook have no source in
 * this repository to be copied from - they are written for the plugin user
 * and exist nowhere else - so they are listed in HAND_WRITTEN one by one,
 * which keeps the rule below: a file under one of the three output folders
 * is generated or named here, nothing else. The commands live in `commands/`
 * rather than as plugin skills because `plugin/skills/` is this script's
 * output and wholly owned by it. The Copilot plugin has no hook: the hook is
 * Claude Code's PostToolUse contract, and Copilot's hook format is a
 * different file - when somebody writes one it goes to HAND_WRITTEN too.
 *
 * A HANDFUL OF SENTENCES DEVIATE, declared below as
 * `[what the source says, what the copy says]`, the way app-template's
 * generate-skills.mjs declares its own. A deviation whose sentence is no
 * longer in the source FAILS rather than being skipped: it means somebody
 * edited a sentence this copy is known to reword, and the two have to be
 * reconciled by hand. Everything else is copied as it is, with one
 * provenance line after the frontmatter that says whose repository "this
 * repository" means - the catalogues name this repository's gates on nearly
 * every line, and those are facts about where a gate lives, not instructions
 * for the plugin user.
 *
 * The Copilot copies of the commands and the agent are translated, not just
 * copied: Claude Code's tool names become Copilot's aliases, the plugin's
 * MCP tool names `mcp__plugin_abap2ui5_abap2ui5__<tool>` become
 * `abap2ui5/<tool>`, `/abap2ui5:<cmd>` becomes the prompt `/abap2ui5-<cmd>`,
 * `$ARGUMENTS` becomes `${input:arguments}`, and the sentences that name
 * `${CLAUDE_PLUGIN_ROOT}` are declared deviations. After that, a copy that
 * still contains a Claude-only token FAILS: a new one in a hand-written
 * command has to be given a translation here before it ships.
 *
 * Every skill under .claude/skills/ is either shipped (SKILLS) or left out
 * with a reason (NOT_SHIPPED) - a new skill cannot slip in or out of the
 * plugin unnoticed. A file under one of the output folders that nothing here
 * writes and that is not named in HAND_WRITTEN fails as well, so a removed
 * skill does not linger in the plugin and a new hand-written file has to be
 * declared. `.github/scripts/plugin-formats.test.mjs` then parses what was
 * written the way the consumers do (npm run check:plugin-formats).
 *
 *   node .github/scripts/generate-plugin.mjs          rewrite the three folders (npm run plugin)
 *   node .github/scripts/generate-plugin.mjs --check  fail if stale            (npm run check:plugin)
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const PLUGIN = 'plugin';
const COPILOT = 'plugin-copilot';
const PORTABLE = 'skills';
const OUTPUTS = [PLUGIN, COPILOT, PORTABLE];
const CHECK = process.argv.includes('--check');

const GUIDE = 'docs/agents/building-apps.md';
const MANIFEST = `${PLUGIN}/.claude-plugin/plugin.json`;
const AGENT = 'abap2ui5-reviewer';
const COMMANDS = ['new-app', 'check', 'find-sample', 'explain', 'add-ai'];

/* The one sentence of build-an-app that says where the guide is - it has a
 * different answer per copy. */
const GUIDE_SENTENCE = '**Read `docs/agents/building-apps.md` in this repository — it is the complete\nself-contained guide**';

/* The interface is in the framework repository, which the plugin user has
 * not checked out - the same rewording in every copy. */
const API_CONTRACT = [
  '- The API contract is `src/02/z2ui5_if_client.intf.abap` — when unsure about',
  '- The API contract is `src/02/z2ui5_if_client.intf.abap` in\n'
  + '  [abap2UI5/abap2UI5](https://github.com/abap2UI5/abap2UI5/blob/main/src/02/z2ui5_if_client.intf.abap)'
  + ' — when unsure about',
];

/* The skills the plugin ships, each with the sentences its copies reword:
 * `claude` for plugin/, `portable` for skills/ and plugin-copilot/. */
const SKILLS = {
  'build-an-app': {
    claude: [
      [
        GUIDE_SENTENCE,
        '**Read `${CLAUDE_PLUGIN_ROOT}/docs/agents/building-apps.md` (the framework\'s\nguide, shipped with this plugin: `docs/agents/building-apps.md` two folders\nabove this skill\'s own) — it is the complete\nself-contained guide**',
      ],
      API_CONTRACT,
    ],
    portable: [
      [
        GUIDE_SENTENCE,
        '**Read `references/building-apps.md` next to this file (the framework\'s\nguide, shipped with this skill) — it is the complete\nself-contained guide**',
      ],
      API_CONTRACT,
    ],
  },
  'view-chain-layout': { claude: [], portable: [] },
  'abap-check': { claude: [], portable: [] },
  'ui5-check': { claude: [], portable: [] },
};

/* Skills under .claude/skills/ the plugin deliberately does not ship, each
 * with the reason. Empty today: all four are for app authors as much as for
 * framework contributors. */
const NOT_SHIPPED = new Map([]);

/* Files under the output folders that are written by hand: the Claude
 * manifest, the READMEs, the slash commands (/abap2ui5:<name>), the subagent,
 * and the PostToolUse hook with its script (tested by
 * .github/scripts/plugin-hook.test.mjs). */
const HAND_WRITTEN = new Set([
  MANIFEST,
  `${PLUGIN}/README.md`,
  ...COMMANDS.map((c) => `${PLUGIN}/commands/${c}.md`),
  `${PLUGIN}/agents/${AGENT}.md`,
  `${PLUGIN}/hooks/hooks.json`,
  `${PLUGIN}/hooks/lint-abap-class.mjs`,
  `${COPILOT}/README.md`,
  `${PORTABLE}/README.md`,
]);

/* What the Copilot copies say instead of the Claude-only sentences. Keyed by
 * the source file under plugin/. Everything else in those files goes through
 * the generic translation below. */
const COPILOT_DEVIATIONS = {
  [`${PLUGIN}/agents/${AGENT}.md`]: [
    [
      'The rules come from the abap2UI5 plugin\'s skills and guide, all readable\nhere:',
      'The rules come from the abap2UI5 plugin\'s skills and guide - load each by\nits name:',
    ],
    ['- `${CLAUDE_PLUGIN_ROOT}/skills/build-an-app/SKILL.md` - the app checklist', '- the `build-an-app` skill - the app checklist'],
    [
      '- `${CLAUDE_PLUGIN_ROOT}/docs/agents/building-apps.md` - the full guide',
      '- `references/building-apps.md` in the `build-an-app` skill - the full guide',
    ],
    ['- `${CLAUDE_PLUGIN_ROOT}/skills/view-chain-layout/SKILL.md` - chain layout', '- the `view-chain-layout` skill - chain layout'],
    ['- `${CLAUDE_PLUGIN_ROOT}/skills/ui5-check/SKILL.md` - UI5 traps (section 1', '- the `ui5-check` skill - UI5 traps (section 1'],
    ['- `${CLAUDE_PLUGIN_ROOT}/skills/abap-check/SKILL.md` - ABAP traps (section 1', '- the `abap-check` skill - ABAP traps (section 1'],
    ['(Grep) for what the class actually uses', '(search) for what the class actually uses'],
    [
      '`&apos;` in `<DESCRIPT>`. Grep for\n   `\\r` and `\\t`. Read and Grep both drop a UTF-8 BOM, so you cannot see\n   whether it is there:',
      '`&apos;` in `<DESCRIPT>`. Search for\n   `\\r` and `\\t`. The read and search tools both drop a UTF-8 BOM, so\n   you cannot see whether it is there:',
    ],
  ],
  [`${PLUGIN}/commands/new-app.md`]: [
    [
      'The abap2UI5 MCP server ships with this plugin (`plugin:abap2ui5:abap2ui5`;\n'
      + 'a copy added with `claude mcp add abap2ui5` exposes the same tools as\n'
      + '`mcp__abap2ui5__*`). When both are there, call the plugin\'s\n'
      + '`mcp__plugin_abap2ui5_abap2ui5__*` ones - this command pre-approves those,\n'
      + 'the other copy asks for permission per tool. If its tools are available,',
      'The abap2UI5 MCP server ships with this plugin as the server `abap2ui5`\n'
      + '(its tools are named `abap2ui5/<tool>` below). If its tools are available,',
    ],
    [
      'Load the `abap2ui5:build-an-app` skill and read the guide it points at,\n`${CLAUDE_PLUGIN_ROOT}/docs/agents/building-apps.md` (chapters 2-5 at least;',
      'Load the `build-an-app` skill and read the guide it ships,\n`references/building-apps.md` (chapters 2-5 at least;',
    ],
  ],
  [`${PLUGIN}/commands/explain.md`]: [
    [
      '`${CLAUDE_PLUGIN_ROOT}/docs/agents/building-apps.md` (MCP `app_guide`), and',
      '`references/building-apps.md` in the `build-an-app` skill (MCP `app_guide`), and',
    ],
  ],
  [`${PLUGIN}/commands/check.md`]: [['- with the Edit tool; a', '- with the edit tool; a']],
  [`${PLUGIN}/commands/find-sample.md`]: [],
  [`${PLUGIN}/commands/add-ai.md`]: [],
};

/* Claude Code's tool names, as Copilot's aliases (the custom-agents
 * configuration reference lists them: execute, read, edit, search, web). */
const TOOL_ALIAS = [
  [/^Read$/, 'read'],
  [/^(Grep|Glob)$/, 'search'],
  [/^(Edit|Write|MultiEdit)$/, 'edit'],
  [/^Bash(\(.*\))?$/, 'execute'],
  [/^(WebFetch|WebSearch)$/, 'web'],
  [/^mcp__plugin_abap2ui5_abap2ui5__(\w+)$/, 'abap2ui5/$1'],
  [/^mcp__abap2ui5__(\w+)$/, 'abap2ui5/$1'],
];

/* Tokens that mean "Claude Code" and may not survive into a Copilot copy.
 * Not inside an identifier: `z2ui5_cl_smps_llm_claude` is a sample class
 * (the Anthropic provider of samples-stack), not Claude Code vocabulary. */
const CLAUDE_ONLY = /(?<![A-Za-z0-9_])(CLAUDE|Claude|claude)|mcp__|\$ARGUMENTS|\/abap2ui5:|`abap2ui5:/;

const provenance = (source) => `<!-- GENERATED by .github/scripts/generate-plugin.mjs from ${source}`
  + ' in abap2UI5/abap2UI5 - "this repository" in the text is the framework\'s.'
  + ' Do not edit; run npm run plugin. -->';

const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');

function rewrite(name, text, deviations) {
  return deviations.reduce((s, [from, to]) => {
    if (!s.includes(from)) {
      throw new Error(
        `${name}: a declared deviation no longer matches the source:\n      ${JSON.stringify(from)}\n`
        + '      the sentence it rewrites was edited or removed - update the deviation in'
        + ' .github/scripts/generate-plugin.mjs',
      );
    }
    return s.split(from).join(to);
  }, text);
}

function splitFrontmatter(source, text) {
  const m = /^---\n([\s\S]*?)\n---\n/.exec(text);
  if (!m) throw new Error(`${source}: no frontmatter (--- name/description ---) at the top`);
  return { block: m[0], fields: m[1], body: text.slice(m[0].length) };
}

const field = (fields, key) => {
  const m = new RegExp(`^${key}:[ \\t]*(.*)$`, 'm').exec(fields);
  return m ? m[1].trim() : null;
};

/* The Agent Skills specification: `name` matches the folder, lower-case
 * letters, digits and single hyphens, 1-64 characters; `description` 1-1024. */
function checkSkillFrontmatter(source, name, fields) {
  const n = field(fields, 'name');
  const d = field(fields, 'description');
  if (n !== name) throw new Error(`${source}: frontmatter name "${n}" is not the folder name "${name}"`);
  if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(n) || n.length > 64) throw new Error(`${source}: "${n}" is not a valid skill name`);
  if (!d || d.length > 1024) throw new Error(`${source}: description missing or over 1024 characters (${d ? d.length : 0})`);
}

/* Frontmatter stays first (every consumer reads `name` and `description`
 * from it), the provenance line goes right below. The portable copy adds the
 * optional fields the specification knows: `license` (the repository's) and
 * a `metadata` map saying where it came from. */
function renderSkill(name, flavour) {
  const source = `.claude/skills/${name}/SKILL.md`;
  const { block, fields, body } = splitFrontmatter(source, read(source));
  checkSkillFrontmatter(source, name, fields);
  const rewritten = rewrite(name, body, SKILLS[name][flavour]);
  const front = flavour === 'portable'
    ? block.replace(/\n---\n$/, '\nlicense: MIT\nmetadata:\n  source: https://github.com/abap2UI5/abap2UI5\n  generated-from: ' + source + '\n---\n')
    : block;
  return `${front}${provenance(source)}\n${rewritten.replace(/\s*$/, '')}\n`;
}

function renderGuide() {
  return `${provenance(GUIDE)}\n\n${read(GUIDE).replace(/\s*$/, '')}\n`;
}

/* Everything Claude-specific in a hand-written command or agent, translated
 * for Copilot; what is left of the Claude vocabulary afterwards is an error. */
function translate(source, text, args) {
  let s = rewrite(source, text, COPILOT_DEVIATIONS[source]);
  s = s.replace(/mcp__plugin_abap2ui5_abap2ui5__(\w+)/g, 'abap2ui5/$1')
    .replace(/mcp__abap2ui5__(\w+)/g, 'abap2ui5/$1')
    .replace(/\/abap2ui5:([a-z0-9-]+)/g, '/abap2ui5-$1')
    .replace(/`abap2ui5:([a-z0-9-]+)`/g, '`$1`')
    .replace(/\$ARGUMENTS/g, args);
  const left = CLAUDE_ONLY.exec(s);
  if (left) {
    const line = s.slice(0, left.index).split('\n').length;
    throw new Error(`${source}:${line}: "${left[0]}" has no Copilot translation - add a deviation to COPILOT_DEVIATIONS`
      + ' in .github/scripts/generate-plugin.mjs');
  }
  return s;
}

function translateTools(source, list, { autoApprove = false } = {}) {
  const out = [];
  for (const raw of list.split(',').map((t) => t.trim()).filter(Boolean)) {
    /* Claude Code's `Bash(npm run check)` pre-approves that one command;
     * Copilot's alias is the whole shell. In a list that grants rather than
     * offers (the CLI command's `allowed-tools`), widening one command to
     * every command would be a permission the source never gave - so it is
     * left out there, and Copilot asks before each shell call. */
    if (autoApprove && /^Bash(\(.*\))?$/.test(raw)) continue;
    const hit = TOOL_ALIAS.find(([re]) => re.test(raw));
    if (!hit) throw new Error(`${source}: the tool "${raw}" has no Copilot alias - add it to TOOL_ALIAS`);
    const alias = raw.replace(hit[0], hit[1]);
    if (!out.includes(alias)) out.push(alias);
  }
  return `[${out.map((t) => JSON.stringify(t)).join(', ')}]`;
}

const copilotProvenance = (source) => `<!-- GENERATED by .github/scripts/generate-plugin.mjs from ${source}`
  + ' in abap2UI5/abap2UI5, translated for GitHub Copilot. Do not edit; run npm run plugin. -->';

/* A Claude Code slash command, twice: as a Copilot CLI command (the same
 * simplified format - `description`, `argument-hint`, `allowed-tools` - the
 * name from the file name, so `/abap2ui5-<cmd>`) and as a VS Code prompt
 * file (`agent: agent` - the prompt runs in agent mode - and `tools`). The
 * tools are Copilot's aliases in both, minus the shell where the list
 * pre-approves (see translateTools). `$ARGUMENTS` becomes the prompt file's
 * input variable; the CLI documents no substitution for commands, so there
 * the sentence names the text typed after the command instead. */
function renderCommand(cmd, shape) {
  const source = `${PLUGIN}/commands/${cmd}.md`;
  const { fields, body } = splitFrontmatter(source, read(source));
  const description = field(fields, 'description');
  const hint = field(fields, 'argument-hint');
  const tools = field(fields, 'allowed-tools');
  if (!description || !tools) throw new Error(`${source}: description and allowed-tools are required`);
  const aliases = translateTools(source, tools, { autoApprove: shape !== 'prompt' });
  const args = shape === 'prompt' ? '${input:arguments}' : 'the text after the command';
  const front = ['---', `description: ${description}`]
    .concat(shape === 'prompt' ? ['agent: agent'] : [])
    .concat(hint ? [`argument-hint: ${hint}`] : [])
    .concat([shape === 'prompt' ? `tools: ${aliases}` : `allowed-tools: ${aliases}`, '---']).join('\n');
  return `${front}\n${copilotProvenance(source)}\n${translate(source, body, args).replace(/\s*$/, '')}\n`;
}

/* The subagent as a Copilot custom agent (`.agent.md`): name, description,
 * tools - the three fields both read the same way. */
function renderAgent() {
  const source = `${PLUGIN}/agents/${AGENT}.md`;
  const { fields, body } = splitFrontmatter(source, read(source));
  const name = field(fields, 'name');
  const description = field(fields, 'description');
  const tools = field(fields, 'tools');
  if (name !== AGENT || !description || !tools) throw new Error(`${source}: name, description and tools are required`);
  const front = ['---', `name: ${name}`, `description: ${description}`, `tools: ${translateTools(source, tools)}`, '---'].join('\n');
  return `${front}\n${copilotProvenance(source)}\n${translate(source, body, '$ARGUMENTS').replace(/\s*$/, '')}\n`;
}

/* The Copilot manifest and MCP file, from the Claude manifest: same name,
 * author, homepage, repository, licence, keywords and server - the component
 * paths are Copilot's own, the description names what this copy carries. */
function copilotManifest() {
  const m = JSON.parse(read(MANIFEST));
  const servers = Object.entries(m.mcpServers ?? {});
  if (servers.length !== 1) throw new Error(`${MANIFEST}: expected exactly one MCP server`);
  const [serverName, server] = servers[0];
  const plugin = {
    name: m.name,
    description: 'Build abap2UI5 apps with GitHub Copilot: the build-an-app, view-chain-layout, abap-check and'
      + ` ui5-check skills, the ${AGENT} custom agent, the /${COMMANDS.map((c) => `abap2ui5-${c}`).join(', /')}`
      + ' commands (prompt files for VS Code), plus the abap2UI5 MCP server (sample search, view validation,'
      + ' deploy, headless run and screenshot - no SAP system needed).',
    author: m.author,
    homepage: m.homepage,
    repository: m.repository,
    license: m.license,
    keywords: [...m.keywords, 'copilot'],
    agents: 'agents/',
    skills: 'skills/',
    commands: 'commands/',
    mcpServers: '.mcp.json',
  };
  const mcp = { mcpServers: { [serverName]: { type: 'stdio', command: server.command, args: server.args, tools: ['*'] } } };
  return { plugin: `${JSON.stringify(plugin, null, 2)}\n`, mcp: `${JSON.stringify(mcp, null, 2)}\n` };
}

function listFiles(dir, out = []) {
  if (!fs.existsSync(path.join(ROOT, dir))) return out;
  for (const entry of fs.readdirSync(path.join(ROOT, dir), { withFileTypes: true })) {
    const rel = `${dir}/${entry.name}`;
    if (entry.isDirectory()) listFiles(rel, out);
    else out.push(rel);
  }
  return out;
}

const problems = [];

/* Every skill is shipped or excluded by name. */
const present = fs.readdirSync(path.join(ROOT, '.claude', 'skills'), { withFileTypes: true })
  .filter((e) => e.isDirectory()).map((e) => e.name).sort();
for (const name of present) {
  if (!(name in SKILLS) && !NOT_SHIPPED.has(name)) {
    problems.push(`.claude/skills/${name} is neither shipped nor excluded - add it to SKILLS in`
      + ' .github/scripts/generate-plugin.mjs, or to NOT_SHIPPED with the reason');
  }
}
for (const name of [...Object.keys(SKILLS), ...NOT_SHIPPED.keys()]) {
  if (!present.includes(name)) {
    problems.push(`generate-plugin.mjs names the skill ${name}, which .claude/skills/ no longer has`
      + ' - drop the entry');
  }
}

const expected = new Map();
try {
  const guide = renderGuide();
  for (const name of Object.keys(SKILLS).filter((n) => present.includes(n))) {
    expected.set(`${PLUGIN}/skills/${name}/SKILL.md`, renderSkill(name, 'claude'));
    const portable = renderSkill(name, 'portable');
    expected.set(`${PORTABLE}/${name}/SKILL.md`, portable);
    expected.set(`${COPILOT}/skills/${name}/SKILL.md`, portable);
  }
  expected.set(`${PLUGIN}/${GUIDE}`, guide);
  expected.set(`${PORTABLE}/build-an-app/references/building-apps.md`, guide);
  expected.set(`${COPILOT}/skills/build-an-app/references/building-apps.md`, guide);
  const { plugin, mcp } = copilotManifest();
  expected.set(`${COPILOT}/plugin.json`, plugin);
  expected.set(`${COPILOT}/.mcp.json`, mcp);
  expected.set(`${COPILOT}/agents/${AGENT}.agent.md`, renderAgent());
  for (const cmd of COMMANDS) {
    expected.set(`${COPILOT}/commands/abap2ui5-${cmd}.md`, renderCommand(cmd, 'command'));
    expected.set(`${COPILOT}/prompts/abap2ui5-${cmd}.prompt.md`, renderCommand(cmd, 'prompt'));
  }
} catch (e) {
  problems.push(e.message);
}

for (const rel of HAND_WRITTEN) {
  if (!fs.existsSync(path.join(ROOT, rel))) problems.push(`${rel} is missing - it is written by hand, not generated`);
}

const stale = [];
if (!problems.length) {
  for (const [rel, text] of expected) {
    const file = path.join(ROOT, rel);
    // Read and catch rather than existsSync-then-read: the check-then-use pair
    // is a file system race (CodeQL js/file-system-race), and a missing file
    // is simply "stale".
    let current = null;
    try {
      current = fs.readFileSync(file, 'utf8');
    } catch (e) {
      if (e.code !== 'ENOENT') throw e;
    }
    if (current === text) continue;
    if (CHECK) {
      stale.push(rel);
    } else {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, text);
      console.log(`generate-plugin: wrote ${rel}`);
    }
  }

  const orphans = OUTPUTS.flatMap((dir) => listFiles(dir)).filter((rel) => !expected.has(rel) && !HAND_WRITTEN.has(rel));
  for (const rel of orphans) {
    if (CHECK) {
      stale.push(`${rel} (nothing generates it)`);
    } else {
      fs.rmSync(path.join(ROOT, rel));
      console.log(`generate-plugin: removed ${rel}`);
    }
  }
}

if (stale.length) {
  problems.push(`${OUTPUTS.join('/, ')}/ are stale - run \`npm run plugin\` and commit the result:\n`
    + stale.map((rel) => `      ${rel}`).join('\n'));
}

if (problems.length) {
  for (const p of problems) console.log(`ERROR ${p}`);
  console.log(`generate-plugin: ${problems.length} error(s).`);
  process.exit(1);
}
console.log(`generate-plugin: ${CHECK ? 'ok' : 'done'} (${expected.size} generated file(s) under ${OUTPUTS.join('/, ')}/,`
  + ` ${Object.keys(SKILLS).length} skill(s), ${HAND_WRITTEN.size} hand-written)`);
